facilityFormItem.valueChangedEventHandler:
          var initiatorId = functions.getValues().InitiatorId;
          var recallDate = formItem.value;
          var vacationId = functions.getValues().VacationId;
          if (recallDate && !context.isFirstTime) {
            var recallDateFromControl = new Date(recallDate).toLocaleDateString('ru-RU', { dateStyle: "long" });
            functions.setValue('Field_Дата выхода на работу', recallDateFromControl);
            var urlGetRecallVacation = `/api/functions/GetRecallVacations?employeeId=${initiatorId}&recallDate=${recallDate}`;
            ESS.network.sendRequest(urlGetRecallVacation)
            .then(function (vacation){
              var isVacation = vacation.id > 0;
              functions.setIsItemDisabled('NewVacationDateGrid', !isVacation, 'BeginDate');
              functions.setIsItemDisabled('NewVacationDateGrid', !isVacation, 'VacationDuration');
              if (isVacation) {
                if (vacation.id != vacationId) {
                  var rows = functions.getValues().NewVacationDateGrid;
                  rows.forEach(row => {
                    functions.removeItem('NewVacationDateGrid', row.rowIndex);
                  });
                  functions.setValue('VacationId', vacation.id);
                  ESS.network.sendRequest(`/api/functions/IsCompensationVisible?vacationId=${vacation.id}`)
                  .then(function (isCompVisible){
                    functions.setIsItemHidden('Compensation', !isCompVisible);
                  });
                }
                else {
                  var rows = functions.getValues().NewVacationDateGrid;
                  var compensation = functions.getValues().Compensation;
                  var vacationKindIdsArray = [];
                  var vacationDurationArray = [];
                  rows.forEach(row => {
                    if (row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
                      vacationKindIdsArray.push(row.rowValues.VacationKindId);
                      vacationDurationArray.push(row.rowValues.VacationDuration);
                    };
                  });

                  ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation: compensation });
                  ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation: compensation });

                  if (vacationKindIdsArray.length > 0) {
                    var urlTemplate = `/api/functions/CheckRecallVacationsDurations?recallDate=${recallDate}&vacationId=${vacationId}&vacationKindIds=[${vacationKindIdsArray}]&durations=[${vacationDurationArray}]&isCompensation=${compensation}&isInfo=false`;
                    ESS.network.sendRequest(urlTemplate).then(function (durationErrors){
                      if(durationErrors.length > 0) {
                        functions.removeError(context.errorDurations);
                        context.errorDurations = functions.showError(durationErrors);
                      } else {
                        functions.removeError(context.errorDurations);
                      }
                    });
                  };
                }
              } else if (vacationId) {
                functions.setValue('VacationId', null);
                functions.setIsItemHidden('Compensation', true);
                functions.setValue('Compensation', false);
                var rows = functions.getValues().NewVacationDateGrid;
                rows.forEach(row => {
                  functions.removeItem('NewVacationDateGrid', row.rowIndex);
                });
              }
            })
            .catch(function (error) {
              ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
            });
          }

facilityFormItem.itemAddedEventHandler:
if (!context.isFirstTime) {
  var vacationId = functions.getValues()['VacationId'];
  if (vacationId) {
    ESS.network.sendRequest(`/api/functions/GetVacationKindIdFromVacationId?vacationId=${vacationId}`)
    .then(function (vacationKindId) {
      var rowindex = functions.getValues().NewVacationDateGrid.length - 1;
      var itemIndex = functions.getValues()['NewVacationDateGrid'][rowindex].rowIndex;
      functions.setValue('NewVacationDateGrid', vacationKindId, itemIndex, 'VacationKindId');
    })
    .catch(error => {
      ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
    });
  }
}

facilityFormItem.itemRemovedEventHandler:
          var recallDate = functions.getValues().RecallDate;
          var vacationId = functions.getValues()['VacationId'];
          var Compensation = functions.getValues().Compensation;
          var rows = functions.getValues().NewVacationDateGrid;
          var vacationKindIdsArray = [];
          var beginDateArray = [];
          var vacationDurationArray = [];
          var endDateArray = [];
          var VacationsData = '';
          rows.forEach(row => {
            if (row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
              vacationKindIdsArray.push(row.rowValues.VacationKindId);
              var beginDate = `"${row.rowValues.BeginDate}"`;
              beginDateArray.push(beginDate);
              vacationDurationArray.push(row.rowValues.VacationDuration);
              var endDate = `"${row.rowValues.EndDate}"`;
              endDateArray.push(endDate);
              VacationsData += row.rowValues.VacationKindId + '~' + row.rowValues.BeginDate + '~' + row.rowValues.EndDate +'!';
            };
          });
          functions.setValue('VacationsData', VacationsData);

          if (vacationId) {
            var urlIsCompensationEnable = `/api/functions/IsCompensationEnable?recallDate=${recallDate}&vacationId=${vacationId}&durations=[${vacationDurationArray}]`;
            ESS.network.sendRequest(urlIsCompensationEnable).then(function (isCompEnable){
              functions.setIsItemDisabled('Compensation', !isCompEnable);
            });

            ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
            ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });

            var urlTemplate = `/api/functions/CheckRecallVacationsDurations?recallDate=${recallDate}&vacationId=${vacationId}&vacationKindIds=[${vacationKindIdsArray}]&durations=[${vacationDurationArray}]&isCompensation=${Compensation}&isInfo=false`;
            ESS.network.sendRequest(urlTemplate).then(function (durationErrors){
              if(durationErrors.length > 0) {
                functions.removeError(context.errorDurations);
                context.errorDurations = functions.showError(durationErrors);
              } else {
                functions.removeError(context.errorDurations);
              }
            });
            var assignmentId = functions.getValues().AssignmentId;
            var urlTemplate = `/api/functions/CheckExecutionShiftVacationsInRework?vacationIds=[${vacationId}]&assignmentId=${assignmentId}`;
            ESS.network.sendRequest(urlTemplate).then(function (errors){
              if(errors.length > 0) {
                functions.removeError(context.errorExecutionShift);
                context.errorExecutionShift = functions.showError(errors);
              } else {
                functions.removeError(context.errorExecutionShift);
              }
            });
          }

column.valueChangedEventHandler:
var today = new Date();
var yesterday = new Date(today);
yesterday.setDate(today.getDate() -1);
var beginDateValue = formItem.value;
var dateFromControl = new Date(beginDateValue).getTime();
functions.removeError(context.errorDate);
if (dateFromControl < yesterday.getTime()) {
  context.errorDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_BEGIN'));
}
var initiatorId = functions.getValues().InitiatorId;
var durationValue = functions.getValues().NewVacationDateGrid.find(function (x) {
  return x.rowIndex === formItem.index;
}).rowValues['VacationDuration'];
var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
  return x.rowIndex === formItem.index;
}).rowValues['VacationKindId'];

if (durationValue != null && beginDateValue != null) {
  var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${initiatorId}&vacationKindId=${vacationKindId}`;
  context.sendRequest(url)
  .then(function (newEndDateValue) {
    functions.setValue('NewVacationDateGrid', newEndDateValue, formItem.index, 'EndDate');
  });
};

              var initiatorId = functions.getValues().InitiatorId;
              var beginDateValue = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['BeginDate'];
              var durationValue = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['VacationDuration'];
              var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['VacationKindId'];
              
              if (durationValue <= 0) {
                functions.removeError(context.errorId);
                context.errorId = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DURATION'));
              } else {
                functions.removeError(context.errorId);
              }

              if (durationValue != null && beginDateValue != null) {
                var endDate = functions.getValues().NewVacationDateGrid.find(function (x) {
                  return x.rowIndex === formItem.index;
                }).rowValues['EndDate'];
                var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${initiatorId}&vacationKindId=${vacationKindId}`;
                context.sendRequest(url)
                .then(function (newEndDateValue) {
                  if (new Date(newEndDateValue).getTime() != new Date(endDate).getTime()) {
                    functions.setValue('NewVacationDateGrid', newEndDateValue, formItem.index, 'EndDate');
                  }
                });
              };

              var initiatorId = functions.getValues().InitiatorId;
              var beginDate = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['BeginDate'];
              var endDate = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['EndDate'];
              var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['VacationKindId'];
              functions.removeError(context.errorEndDate);
              if (beginDate != null && endDate != null && vacationKindId != null) {
                var checkUrl = `/api/functions/CheckVacationHasHoliday?periodBegin=${beginDate}&periodEnd=${endDate}&employeeId=${initiatorId}&vacationKindId=${vacationKindId}`;
                context.sendRequest(checkUrl)
                .then(function (warning) {
                  if(warning.length > 0)
                    ESS.toasts.showToast(warning, ESS.enums.ToastType.ERROR, true);
                });

                var url = `/api/functions/DurationInCalendarDaysWithoutHoliday?startDate=${beginDate}&endDate=${endDate}&userId=${initiatorId}&vacationKindId=${vacationKindId}`
                context.sendRequest(url)
                .then(function (newDuration) {
                  if (newDuration <= 0) {
                    context.errorEndDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_END'));
                  }
                  else {
                    var recallDate = functions.getValues().RecallDate;
                    var vacationId = JSON.parse(functions.getValues()['VacationId']);
                    var compensation = functions.getValues().Compensation;
                    var rows = functions.getValues().NewVacationDateGrid;
                    var vacationKindIdsArray = [];
                    var beginDateArray = [];
                    var vacationDurationArray = [];
                    var endDateArray = [];
                    var VacationsData = '';
                    rows.forEach(row => {
                      if (row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
                        vacationKindIdsArray.push(row.rowValues.VacationKindId);
                        var beginDate = `"${row.rowValues.BeginDate}"`;
                        beginDateArray.push(beginDate);
                        vacationDurationArray.push(row.rowValues.VacationDuration);
                        var endDate = `"${row.rowValues.EndDate}"`;
                        endDateArray.push(endDate);
                        VacationsData += row.rowValues.VacationKindId + '~' + row.rowValues.BeginDate + '~' + row.rowValues.EndDate +'!';
                      };
                    });
                    functions.setValue('VacationsData', VacationsData);

                    var urlIsCompensationEnable = `/api/functions/IsCompensationEnable?recallDate=${recallDate}&vacationId=${vacationId}&durations=[${vacationDurationArray}]`;
                    context.sendRequest(urlIsCompensationEnable).then(function (isCompEnable){
                      functions.setIsItemDisabled('Compensation', !isCompEnable);
                      if (!isCompEnable)
                        functions.setValue('Compensation', false);
                    });

                    if (vacationId !== null){
                      ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation: compensation });
                    }
                    if (vacationKindIdsArray.length > 0) {
                      ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation: compensation });
                    };

                    var url = `/api/functions/CheckVacationRequiredDuration?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
                    context.sendRequest(url)
                    .then(function (errors) {
                      if (errors.length > 0){
                        var toastId = ESS.toasts.showToast(errors, ESS.enums.ToastType.ERROR, true);
                      }
                    });

                    var urlTemplate = `/api/functions/CheckAllVacationShiftDates?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
                    context.sendRequest(urlTemplate).then(function (errors){
                      if(errors.length > 0) {
                        functions.removeError(context.errorVacations);
                        context.errorVacations = functions.showError(errors);
                      } else {
                        functions.removeError(context.errorVacations);
                      }
                    });
                    if (vacationKindIdsArray.length > 0) {
                      var urlTemplate = `/api/functions/CheckRecallVacationsDurations?recallDate=${recallDate}&vacationId=${vacationId}&vacationKindIds=[${vacationKindIdsArray}]&durations=[${vacationDurationArray}]&isCompensation=${compensation}&isInfo=false`;
                      context.sendRequest(urlTemplate).then(function (durationErrors){
                        if(durationErrors.length > 0) {
                          functions.removeError(context.errorDurations);
                          context.errorDurations = functions.showError(durationErrors);
                        } else {
                          functions.removeError(context.errorDurations);
                        }
                      });
                    };
                    var assignmentId = functions.getValues().AssignmentId;
                    var urlTemplate = `/api/functions/CheckExecutionShiftVacationsInRework?vacationIds=[${vacationId}]&assignmentId=${assignmentId}`;
                    context.sendRequest(urlTemplate).then(function (errors){
                      if(errors.length > 0) {
                        functions.removeError(context.errorExecutionShift);
                        context.errorExecutionShift = functions.showError(errors);
                      } else {
                        functions.removeError(context.errorExecutionShift);
                      }
                    });
                  }
                });
              }

facilityFormItem.valueChangedEventHandler:
          var recallDate = functions.getValues().RecallDate;
          var vacationId = JSON.parse(functions.getValues()['VacationId']);
          var Compensation = formItem.value;
          functions.setIsItemDisabled('NewVacationDateGrid', Compensation, 'BeginDate');
          functions.setIsItemDisabled('NewVacationDateGrid', Compensation, 'VacationDuration');
          var rows = functions.getValues().NewVacationDateGrid;
          var vacationKindIdsArray = [];
          var vacationDurationArray = [];
          rows.forEach(row => {
            if (row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
              vacationKindIdsArray.push(row.rowValues.VacationKindId);
              vacationDurationArray.push(row.rowValues.VacationDuration);
            };
          });

          if (vacationId){
            ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
          }
          if (vacationKindIdsArray.length > 0) {
            ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
          };

          if (vacationId && vacationKindIdsArray.length > 0) {
            var urlTemplate = `/api/functions/CheckRecallVacationsDurations?recallDate=${recallDate}&vacationId=${vacationId}&vacationKindIds=[${vacationKindIdsArray}]&durations=[${vacationDurationArray}]&isCompensation=${Compensation}&isInfo=false`;
            ESS.network.sendRequest(urlTemplate).then(function (durationErrors){
              if(durationErrors.length > 0) {
                functions.removeError(context.errorDurations);
                context.errorDurations = functions.showError(durationErrors);
              } else {
                functions.removeError(context.errorDurations);
              }
            });
          };

          var urlTemplate = `/api/functions/CheckExecutionShiftVacationsInRework?vacationIds=[${vacationId}]&assignmentId=${functions.getValues().AssignmentId}`;
          context.sendRequest(urlTemplate).then(function (errors){
          functions.removeError(context.errorExecutionShift);
          if(errors.length > 0) {            
            context.errorExecutionShift = functions.showError(errors);
          }
        });

facilityFormItem.onClickEventHandler:
        const id = 'selfRecallVacationSimplePlanningTool';
        let intervalId;
        const callDialog = () => {
          if (!Object.keys(context.canShowDialog).length) {
            const timeline = {
              type: ESS.enums.DialogItemType.TEXT,
              name: 'timeline',
              properties: {
                text: `
                  <component
                    name="VacationPlanningTool"
                    public-name="Directum_VacationPlanningTool_1_0"
                    module-name="loaders"
                    loader-name="lk-loader"
                    dialog-id="${id}"
                  />
                `,
              },
            };

            const newVacations = {
              type: ESS.enums.DialogItemType.INPUT,
                name: 'Vacations',
                properties: {
                  initialValue: JSON.stringify(functions.getValues().NewVacationDateGrid),
                  isHidden: true,
                },
            }

            const oldVacations = {
              type: ESS.enums.DialogItemType.INPUT,
                name: 'OldVacations',
                properties: {
                  initialValue: JSON.stringify([functions.getValues().VacationId]),
                  isHidden: true,
                },
            }

            const recallDate = {
              type: ESS.enums.DialogItemType.INPUT,
                name: 'RecallDate',
                properties: {
                  initialValue: functions.getValues().RecallDate,
                  isHidden: true,
                },
            }

            const performerId = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'PerformerId',
              properties: {
                initialValue: functions.getValues().InitiatorId,
                isHidden: true,
              },
            };

            const entityGuid = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'EntityGuid',
              properties: {
                initialValue: 'cbd8fbf7-e341-4f84-8e13-d8cb8e41f7ff',
                isHidden: true,
              },
            };

            const compensation = {
              type: ESS.enums.DialogItemType.CHECKBOX,
              name: 'Compensation',
              properties: {
                initialValue: functions.getValues().Compensation,
                isHidden: true,
              },
            };

            const items = [
              timeline,
              performerId,
              newVacations,
              oldVacations,
              recallDate,
              entityGuid,
              compensation,
            ];

            ESS.dialogs.createDialog({
              id,
              properties: {
                width: ESS.enums.DialogWidth.WIDE,
              },
              title: ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_DIALOG_TITLE'),
              items,
            });
            clearInterval(intervalId);
          }
        }

        intervalId = setInterval(callDialog, 300);

facility.openingEventHandler:
      context.canShowDialog = {};
      context.sendRequest = (...args) => {
        const key = Date.now();
        context.canShowDialog[key] = '';
        return ESS.network.sendRequest(...args).finally(() => delete context.canShowDialog[key]);
      };
      ESS.network.sendRequest(`/api/functions/GetCurrentRecallVacation?assignmentId=${functions.getValues().AssignmentId}`)
      .then(function (OldRecallVacation) {
        context.isFirstTime = true;
        var recallDate = OldRecallVacation.RecallDate;
        var vacationId = OldRecallVacation.VacationId;
        var initiatorId = OldRecallVacation.InitiatorId;
        var reason = OldRecallVacation.Reason;
        var newVacationData = OldRecallVacation.NewVacationData;
        var compensation = OldRecallVacation.Compensation;

        functions.setValue('InitiatorId', initiatorId);
        functions.setValue('RecallDate', recallDate);
        functions.setValue('VacationId', vacationId);
        functions.setValue('Compensation', compensation);
        functions.setValue('Reason', reason);

        functions.setValue('Field_Причина', reason);
        var recallDateFromControl = new Date(recallDate).toLocaleDateString('ru-RU', { dateStyle: "long" });
        functions.setValue('Field_Дата выхода на работу', recallDateFromControl);

        var vacationKindIdsArray = [];
        var beginDateArray = [];
        var vacationDurationArray = [];
        var endDateArray = [];
        var VacationsData = '';
        var rows = functions.getValues().NewVacationDateGrid;
        if (newVacationData.length > 0){
          for (var i = 0; i < newVacationData.length; i++) {
            var rowIndex = rows.length > i ? rows[i]['rowIndex'] : functions.addItem('NewVacationDateGrid');
            functions.setValue('NewVacationDateGrid', newVacationData[i]['VacationKindId'], rowIndex, 'VacationKindId');
            functions.setValue('NewVacationDateGrid', newVacationData[i]['Begin'], rowIndex, 'BeginDate');
            functions.setValue('NewVacationDateGrid', newVacationData[i]['Duration'], rowIndex, 'VacationDuration');
            functions.setValue('NewVacationDateGrid', newVacationData[i]['End'], rowIndex, 'EndDate');
            vacationKindIdsArray.push(newVacationData[i]['VacationKindId']);
            var beginDate = `"${newVacationData[i]['Begin']}"`;
            beginDateArray.push(beginDate);
            vacationDurationArray.push(newVacationData[i]['Duration']);
            var endDate = `"${newVacationData[i]['End']}"`;
            endDateArray.push(endDate);
            VacationsData += newVacationData[i]['VacationKindId'] + '~' + newVacationData[i]['Begin'] + '~' + newVacationData[i]['End'] +'!';
          }
        }
        functions.setValue('VacationsData', VacationsData);

        var url = `/api/functions/CheckVacationRequiredDuration?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
        ESS.network.sendRequest(url)
        .then(function (errors) {
          if (errors.length > 0){
            var toastId = ESS.toasts.showToast(errors, ESS.enums.ToastType.ERROR, true);
          }
        });

        functions.setIsItemDisabled('NewVacationDateGrid', compensation, 'BeginDate');
        functions.setIsItemDisabled('NewVacationDateGrid', compensation, 'VacationDuration');

        ESS.network.sendRequest(`/api/functions/IsCompensationVisible?vacationId=${vacationId}`)
        .then(function (isCompVisible){
          functions.setIsItemHidden('Compensation', !isCompVisible);
        });
        var urlIsCompensationEnable = `/api/functions/IsCompensationEnable?recallDate=${recallDate}&vacationId=${vacationId}&durations=[${vacationDurationArray}]`;
        ESS.network.sendRequest(urlIsCompensationEnable).then(function (isCompEnable){
          functions.setIsItemDisabled('Compensation', !isCompEnable);
          if (!isCompEnable)
            functions.setValue('Compensation', false);
        });
        
        var urlIsInitiateByManager = `/api/functions/IsInitiateByManagerInAssignment?assignmentId=${functions.getValues().AssignmentId}`;
        ESS.network.sendRequest(urlIsInitiateByManager)
        .then(function (InitiateByManager){
          functions.setValue('InitiateByManager', InitiateByManager);
          ESS.network.sendRequest(`/api/functions/GetVacationRecallStatementTemplateId?employeeId=${initiatorId}&isShiftVacation=false&isVacationRecall=true&isAuthorManager=${InitiateByManager}`)
          .then(function (VacationStatementData) {
            var templateId = JSON.parse(VacationStatementData.TemplateId);
            var docKindId = JSON.parse(VacationStatementData.DocumentKindId);
            functions.setValue('TemplateId', templateId);
            functions.setValue('DocumentKindId', docKindId);
          });
        })
        .catch(function (error) {
          ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
        });

        ESS.network.sendRequest(`/api/functions/GetShiftVacationStatementId?assignmentId=${functions.getValues().AssignmentId}`)
        .then(function (statementId){
          functions.setValue('StatementId', statementId);
        })
        .catch(function (error) {
          ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
        });
        
        ESS.network.sendRequest(`/api/functions/GetPostListByPerson`)
        .then(function (emps) {
          if (emps.positions.length > 1){
            functions.setValue('Department', OldRecallVacation.Department);
            functions.setValue('BusinessUnit', OldRecallVacation.Organization);
            functions.setValue('JobTitle', OldRecallVacation.JobTitle);
          }
        })

        ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation: compensation });
        context.isFirstTime = false;
        resolve();      
      })
      .catch(function (error) {
        ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
      });
